  List<int> lam = List<int>.filled(N + 1, 0);
  List<Node> nodes = List<Node>.generate(N + 1, (_) => Node());

  // Make triply linked tree
  int t = 0;
  for (int v = N; v > 0; v--) {
    int u = 0;
    while (A[v] > A[t] || (A[v] == A[t] && v > t)) {
      u = t;
      t = nodes[t].parent;
    }

    if (u != 0) {
      nodes[v].sib = nodes[u].sib;
      nodes[u].sib = 0;
      nodes[u].parent = v;
      nodes[v].child = u;
    } else {
      nodes[v].sib = nodes[t].child;
    }

    nodes[t].child = v;
    nodes[v].parent = t;
    t = v;
  }

  // Begin first traversal
  int p = nodes[0].child;
  int n = 0;
  lam[0] = -1;

